coins = 12
bonus = 5
result = {'сумма': coins + bonus, 'разность': coins - bonus, 'произведение': coins * bonus}
assert result == {'сумма': 17, 'разность': 7, 'произведение': 60}
for operation, value in result.items():
    print(operation, '=', value)

def largest(values):
    if not values:
        raise ValueError('Нужен хотя бы один элемент')
    best = values[0]
    for value in values[1:]:
        if value > best:
            best = value
    return best
scores = [-8, -2, -11, -5]
assert largest(scores) == -2
assert largest([7]) == 7
assert max(scores) == largest(scores)
print('Лучший результат:', largest(scores))
